def seed(apps, schema_editor):
    ScKpi = apps.get_model("staff_management", "ScKpi")
    ScRole = apps.get_model("staff_management", "ScRole")
    ScRoleKpiMapping = apps.get_model("staff_management", "ScRoleKpiMapping")

    if ScKpi.objects.exists() or ScRoleKpiMapping.objects.exists():
        print("\n  scorecard config: already present - left alone.")
        return

    for code, name in ROLES.items():
        ScRole.objects.get_or_create(
            role_code=code,
            defaults={"role_name": name, "role_type": "IC", "is_active": True})

    inactive = 0
    for row in KPIS:
        row = dict(row)
        reason = row.pop("not_configured_reason", "")
        ScKpi.objects.create(
            kpi_calculation_mode="actual_over_target",
            kpi_rating_type="prorate",
            score_cap="1.20",
            is_active=not reason,
            not_configured_reason=reason,
            **row)
        if reason:
            inactive += 1

    start, end = date(YEAR, 1, 1), date(YEAR, 12, 31)
    for row in MAPPINGS:
        row = dict(row)
        row.pop("role_name", None)
        target = row.pop("kpi_target", None)
        ScRoleKpiMapping.objects.create(
            effective_from=start, effective_to=end,
            bonus_effective_from=start, bonus_effective_to=end,
            plan_category="p1", target_category="full_year", prorate=True,
            kpi_target=target,
            **row)

    print(f"\n  scorecard config: {len(ROLES)} roles, {len(KPIS)} KPIs "
          f"({inactive} awaiting a block), {len(MAPPINGS)} mappings.")


def unseed(apps, schema_editor):
    """Nothing to undo - removing a desk's configuration to reverse a seed
    would destroy tuning this migration never made."""


class Migration(migrations.Migration):

    dependencies = [
        ("staff_management", "0026_sc_kpi_allocation_column"),
    ]

    operations = [
        migrations.RunPython(seed, unseed),
    ]
